update public.learning_paths
set
  title = 'Directing I',
  goal = 'Directing I',
  summary = 'Directing I introduces students to the director''s craft as interpretation, leadership, rehearsal design, actor collaboration, visual composition, and production communication. Students move from script analysis and concept work into practical staging exercises and a directed scene project.',
  data = $dir1json${"slug": "directing-i", "title": "Directing I", "description": "Directing I introduces students to the director's craft as interpretation, leadership, rehearsal design, actor collaboration, visual composition, and production communication. Students move from script analysis and concept work into practical staging exercises and a directed scene project.", "topics": [{"id": "e647bf55-5ebf-45b9-971b-9300a49f9aff", "type": "topic", "title": "The Director's Vision", "description": "This section frames directing as interpretive leadership. Students learn to articulate a clear reason for a production and translate that reason into choices the whole team can use.", "children": [{"id": "42da9df3-f387-425d-b998-816143f6f5f7", "type": "subtopic", "title": "Point of view and purpose", "children": [{"id": "a72592be-90f6-4356-ad5d-c2a7137667d4", "type": "concept", "title": "Why this play now"}, {"id": "3435fa92-bcff-4135-8442-48a3103983f8", "type": "concept", "title": "Audience and community"}, {"id": "0cc575fd-301d-4b62-8b5b-06d5377d9b36", "type": "concept", "title": "Personal response versus production purpose"}], "description": "The goal is to move beyond liking a play toward making an argument for why it belongs on stage now."}, {"id": "80325a89-5a61-4012-9c76-0d2810dc284b", "type": "subtopic", "title": "Theatrical world and rules", "children": [{"id": "24661fd0-333f-4282-b89d-1d3fdb433ead", "type": "concept", "title": "Realism and theatricality"}, {"id": "3982e096-eed1-4ca4-9a95-e6ad290c75f9", "type": "concept", "title": "Rules of space and time"}, {"id": "2851ac7b-8fc4-497b-8e30-2983955974a7", "type": "concept", "title": "Tone and genre expectations"}], "description": "Students define the world the production asks the audience to enter, including its style, behavior, time, and sensory logic."}, {"id": "0a637b1b-9018-4bcf-b4d4-569a1abcedd7", "type": "subtopic", "title": "Director's statement", "children": [{"id": "52e24eeb-b985-495f-a9ec-6a34df77e5da", "type": "concept", "title": "One-sentence premise"}, {"id": "58af7386-0ffa-4f77-a979-3b9f69d596a1", "type": "concept", "title": "Core image or question"}, {"id": "0f202d19-5657-477b-84c3-34067fa13a45", "type": "concept", "title": "Language for actors and designers"}], "description": "A short statement helps collaborators understand the production's north star without closing down discovery."}, {"id": "12c51570-0a3f-4888-b612-09000abdfb96", "type": "subtopic", "title": "Ethical and cultural stakes", "children": [{"id": "d0452894-ceac-48ab-80fb-7ad33c91cd48", "type": "concept", "title": "Representation and harm"}, {"id": "26dca003-89b2-4377-a803-0c4275ab7962", "type": "concept", "title": "Community context"}, {"id": "52a7e911-9b2d-4fab-8107-a09bf0c82773", "type": "concept", "title": "Consultation and accountability"}], "description": "Vision includes responsibility for the social meanings the production creates."}]}, {"id": "8c25921f-ddbe-4b0f-b450-416008904ac0", "type": "topic", "title": "Script Analysis for Directors", "description": "Directors analyze scripts to discover action, event, relationship, structure, and playable choices. The point is to prepare for rehearsal, not only to write about literature.", "children": [{"id": "10dca246-024d-408e-b2a2-ebd0c52eeef3", "type": "subtopic", "title": "Dramatic action and events", "children": [{"id": "6645b502-0807-4aa3-b93d-fb0b62b55442", "type": "concept", "title": "Event mapping"}, {"id": "573b45e3-58a7-4133-9cd7-d61e5594ed60", "type": "concept", "title": "Triggers and consequences"}, {"id": "fc8fbc3b-f1b3-46a9-8613-8837928a050f", "type": "concept", "title": "Scene objectives"}], "description": "Students learn to find what changes in a scene and why that change matters."}, {"id": "9306717d-d19a-42d3-9589-4254af500d23", "type": "subtopic", "title": "Character objectives and obstacles", "children": [{"id": "858626f6-5898-4668-b515-68d750f76448", "type": "concept", "title": "Want and need"}, {"id": "397ce9ce-6302-4ad8-9f25-6372c4958455", "type": "concept", "title": "Obstacles"}, {"id": "976d163f-9649-4f0b-a7bf-fc7bceaf9a31", "type": "concept", "title": "Tactics and adjustments"}], "description": "Directors need actor-friendly language for desire, resistance, tactics, and stakes."}, {"id": "d2e84c7a-02cf-4464-b418-fed858716f12", "type": "subtopic", "title": "Structure, rhythm, and arc", "children": [{"id": "ec3d65ca-b671-40f4-88b7-fb21c047ffd4", "type": "concept", "title": "Beats and units"}, {"id": "867b43fc-26cf-4d77-acd3-482480c9d171", "type": "concept", "title": "Rising and falling action"}, {"id": "5ee8ab44-9d7f-4f28-98b5-3591a525eef7", "type": "concept", "title": "Reversals and discoveries"}], "description": "Students learn how scenes build pressure and how a full play organizes audience attention."}, {"id": "eb0ccc52-3262-4bef-8c21-b6d0712f990d", "type": "subtopic", "title": "Production demands", "children": [{"id": "80d17ccb-f6d4-4c2c-bf39-674b548481d0", "type": "concept", "title": "Designable moments"}, {"id": "05041c4f-3397-44c4-82ee-53c5032aaac5", "type": "concept", "title": "Special skills and safety"}, {"id": "9bfccee2-b8ef-4461-b3fe-f31d6eebb989", "type": "concept", "title": "Research questions"}], "description": "Analysis also identifies staging, design, casting, intimacy, violence, dialect, and access needs."}]}, {"id": "7c135adf-f18e-4ea0-9cf9-7574646b3e07", "type": "topic", "title": "Concept Development", "description": "Concept development turns analysis into a practical artistic frame. Students learn to make choices that are specific enough to guide rehearsal and flexible enough to evolve.", "children": [{"id": "70a941aa-5a60-4483-ab4f-58a520e0b1e4", "type": "subtopic", "title": "Research into concept", "children": [{"id": "401206fb-e5cb-4e7c-8fe7-189dc4fa3c0f", "type": "concept", "title": "Research packets"}, {"id": "aafd1f95-54f4-4207-9e0e-1221b3287da3", "type": "concept", "title": "Visual references"}, {"id": "925911c7-6e02-4f42-9b92-91e1aab81271", "type": "concept", "title": "Historical pressure points"}], "description": "Students practice converting historical, social, visual, and dramaturgical research into a coherent production idea."}, {"id": "40f26dac-3efa-4723-8c56-43586e30e642", "type": "subtopic", "title": "Style and genre", "children": [{"id": "59d81b05-8106-4b4e-9f60-1fb4e58673fe", "type": "concept", "title": "Comedic and tragic rhythm"}, {"id": "486231c2-272c-401a-80d4-1386cbd19a51", "type": "concept", "title": "Period and adaptation"}, {"id": "89863d17-7e2c-4bf5-8e47-8ed34fc31a3b", "type": "concept", "title": "Physical and verbal style"}], "description": "The director decides how the production behaves theatrically, from realism to heightened form."}, {"id": "42beaf0d-5346-4a51-b362-5c77e3c1fec5", "type": "subtopic", "title": "Concept testing", "children": [{"id": "2035178d-da6c-4e86-a9f6-6ef45e91474e", "type": "concept", "title": "Scene experiments"}, {"id": "2d89dbc5-9265-4ae5-a557-f9e96314a02d", "type": "concept", "title": "Design feasibility"}, {"id": "5fa45196-5f66-48a9-afe9-92781de7c950", "type": "concept", "title": "Actor improvisation as research"}], "description": "A strong concept survives contact with actors, space, budget, and audience needs."}, {"id": "b8de18e4-da04-4865-ad14-b93d962a944e", "type": "subtopic", "title": "Communicating concept", "children": [{"id": "ce442ad7-dca1-4d0a-80c6-88f618791759", "type": "concept", "title": "Pitch language"}, {"id": "74339adb-984f-4288-8e55-e35711fa9ab5", "type": "concept", "title": "Mood boards"}, {"id": "35a989f1-d769-4914-befd-69e78559ab53", "type": "concept", "title": "Questions for collaborators"}], "description": "Students learn to present concept without jargon and invite collaborators into the process."}]}, {"id": "3c260cb6-6622-4728-bcba-d6f5dfc31f9b", "type": "topic", "title": "Casting", "description": "Casting is both artistic composition and ethical responsibility. Students learn how casting choices shape meaning, rehearsal room trust, and audience interpretation.", "children": [{"id": "7ec9044d-2fc0-4862-8f84-54663a415bf8", "type": "subtopic", "title": "Audition design", "children": [{"id": "043ff5d2-cea1-4d70-b8e3-597486e3c32d", "type": "concept", "title": "Sides and monologues"}, {"id": "1ca50ee5-3f4a-4659-a6f7-347ff84d802e", "type": "concept", "title": "Callbacks"}, {"id": "7b680d63-bb3c-41f9-95a1-414d0c478948", "type": "concept", "title": "Clear audition instructions"}], "description": "The point is to build auditions that reveal relevant skills and support performers doing good work."}, {"id": "9fcfcb42-0d45-47bf-80bc-bd6a59e1d0c8", "type": "subtopic", "title": "Ensemble composition", "children": [{"id": "4732c57b-fa99-46ff-b00d-ff7dfcdc18bc", "type": "concept", "title": "Relationships and status"}, {"id": "753390a0-2027-4964-abe6-d5a3100e8962", "type": "concept", "title": "Vocal and physical range"}, {"id": "83e6686f-41e5-41a2-8e76-4cdb16d6b9da", "type": "concept", "title": "Ensemble dynamics"}], "description": "Students consider chemistry, contrast, balance, and the social world created by the cast."}, {"id": "dd1cecdb-ed4e-4e9a-aceb-03d6cdca9b43", "type": "subtopic", "title": "Ethical casting practice", "children": [{"id": "97148794-989b-4a3f-8e27-b91a90f4cd46", "type": "concept", "title": "Identity-conscious casting"}, {"id": "7c9567c2-fdf0-4d5b-b0b0-1d4bf1a27ef4", "type": "concept", "title": "Accessible auditions"}, {"id": "c72fe63f-f54e-4ce1-a4ff-e55272f306be", "type": "concept", "title": "Avoiding tokenism and harm"}], "description": "Directors must understand representation, access, consent, and the limits of their own perspective."}, {"id": "34d093cb-65c7-4321-a7b8-30ee20b574a0", "type": "subtopic", "title": "Casting communication", "children": [{"id": "6ac6b2c2-c937-4f11-b3cd-53ba411d4a76", "type": "concept", "title": "Room etiquette"}, {"id": "3f5fd426-7358-44e4-89fd-fbc514a00566", "type": "concept", "title": "Feedback boundaries"}, {"id": "6bfa9bf3-26c1-4344-a191-d81104a6e2b4", "type": "concept", "title": "Offer and rejection practices"}], "description": "Professional communication protects dignity before, during, and after auditions."}]}, {"id": "ffbc3ff2-d591-43b4-b6ba-5bd522ef3325", "type": "topic", "title": "Blocking and Stage Composition", "description": "Blocking is visual storytelling through bodies, space, focus, and movement. Students learn to stage action so the audience understands relationship and change.", "children": [{"id": "ad197dbe-10a7-4ee3-a494-21cdcdfb2262", "type": "subtopic", "title": "Focus and composition", "children": [{"id": "c25e7f24-79ba-44d2-ab2c-e95a10a90756", "type": "concept", "title": "Stage pictures"}, {"id": "c57014c9-8135-40c5-aece-a6ec72a91c8c", "type": "concept", "title": "Levels and planes"}, {"id": "e8b3a1a4-edc5-410c-81e0-5ab1e5d75d15", "type": "concept", "title": "Sightlines and focus"}], "description": "Students learn how grouping, levels, distance, and orientation guide the audience's eye."}, {"id": "bc1b99df-22e3-47aa-a310-07138ff9a9f9", "type": "subtopic", "title": "Movement motivated by action", "children": [{"id": "f80736d9-c109-4801-bd81-b073fa585504", "type": "concept", "title": "Entrances and exits"}, {"id": "099242c2-f2a3-44d8-bc52-87df7b6315ef", "type": "concept", "title": "Crosses and turns"}, {"id": "3d3dfbd0-4a22-4b48-911d-dcddf98a7179", "type": "concept", "title": "Motivated stillness"}], "description": "Blocking should come from character need and dramatic event, not decorative traffic."}, {"id": "9806a05d-2e7a-46f2-a2e7-c96074c0d606", "type": "subtopic", "title": "Spatial relationships", "children": [{"id": "e5b85b14-74fb-464b-ad20-884e0b0bed54", "type": "concept", "title": "Proxemics"}, {"id": "a15e1bab-04ee-4693-9ad7-564b1c6b01bb", "type": "concept", "title": "Power and vulnerability"}, {"id": "846239b9-0d51-45cc-b560-9c03b86b0c69", "type": "concept", "title": "Public versus private space"}], "description": "Distance and placement reveal status, intimacy, conflict, isolation, and alliance."}, {"id": "4ba5f2a2-1340-4759-9113-345eafae978d", "type": "subtopic", "title": "Notation and revision", "children": [{"id": "a63cf138-e571-4396-9ab9-3e0ddc59453f", "type": "concept", "title": "Ground plans"}, {"id": "2d93a704-b0a7-480e-a585-93f9ff477fcd", "type": "concept", "title": "Blocking notation"}, {"id": "ca2581d6-5846-48da-8281-253072617569", "type": "concept", "title": "Stage management coordination"}], "description": "Students document blocking and revise it as performance discoveries emerge."}]}, {"id": "ece24c4c-1c08-4d99-83ae-faf47ecdf599", "type": "topic", "title": "Working with Actors", "description": "Directing actors requires precise language, trust, listening, and respect for process. Students learn how to guide performance without controlling every impulse.", "children": [{"id": "4c246b00-514f-47d7-ba64-55c23edbfa08", "type": "subtopic", "title": "Playable notes", "children": [{"id": "bf5914e0-bc46-405c-bfe6-8d2f3e496583", "type": "concept", "title": "Action verbs"}, {"id": "db103ed6-16bb-4a82-89e6-028cd12f10c0", "type": "concept", "title": "Objectives and tactics"}, {"id": "93149fd6-715e-4b29-b7db-85daad574b3a", "type": "concept", "title": "Avoiding line readings"}], "description": "Students learn to give notes actors can act, rather than abstract judgments or results-only instructions."}, {"id": "72ed0659-3050-4bb9-8a53-cc07e2eecfd8", "type": "subtopic", "title": "Rehearsal room trust", "children": [{"id": "43c959d9-6d54-4ccf-8b80-3ae7a59e722b", "type": "concept", "title": "Room agreements"}, {"id": "7661580e-1620-45c0-9455-15d56e01118b", "type": "concept", "title": "Consent and intimacy boundaries"}, {"id": "49e08bb1-11e0-4d1f-8a47-0d80a60563e2", "type": "concept", "title": "Psychological safety"}], "description": "The director sets the conditions for risk, rigor, consent, and creative honesty."}, {"id": "53b66d63-6141-4b2a-bc71-50657ffb10fa", "type": "subtopic", "title": "Improvisation and exploration", "children": [{"id": "02a165ea-5997-4c0a-bda7-e94983c3e823", "type": "concept", "title": "Status exercises"}, {"id": "3ed401b8-6144-40ed-8c72-bdf8b1e5f1fb", "type": "concept", "title": "Backstory improvisation"}, {"id": "027cf1c5-5afe-408c-8986-260762f1a68a", "type": "concept", "title": "Physical score experiments"}], "description": "Exercises can unlock relationship, given circumstances, rhythm, and physical choices."}, {"id": "dee122ed-d05f-477a-896a-1c908c7c109a", "type": "subtopic", "title": "Performance consistency", "children": [{"id": "74cdf90d-7b3d-4e70-86f4-e1f4da762d12", "type": "concept", "title": "Notes after runs"}, {"id": "add77d6a-760b-4596-b732-c3f1183e1c3e", "type": "concept", "title": "Cue and objective reminders"}, {"id": "ba70cb5b-7e78-4ca7-98c9-07f960eec04e", "type": "concept", "title": "Avoiding over-direction"}], "description": "Students learn how to help actors repeat discoveries while keeping performance alive."}]}, {"id": "3bd88ea4-d7c1-4a2a-a48b-0efde90e1e25", "type": "topic", "title": "Rehearsal Planning and Structure", "description": "A director's plan turns limited time into focused discovery. Students learn to organize rehearsals that balance table work, experimentation, staging, repetition, and notes.", "children": [{"id": "ff0ea278-7bb7-4676-9578-4d691ca1f219", "type": "subtopic", "title": "Process architecture", "children": [{"id": "81efe1c7-5a80-42ec-aeba-89bf54f10d06", "type": "concept", "title": "Table work"}, {"id": "128058c9-a01d-44f3-a7d7-bb89bccd8567", "type": "concept", "title": "Blocking rehearsals"}, {"id": "06fa8883-b799-49af-adab-c4b63a8742c4", "type": "concept", "title": "Runs and polishing"}], "description": "Students map the rehearsal journey from first read to performance."}, {"id": "603a1da1-4001-4085-b3c2-3477df76c62f", "type": "subtopic", "title": "Daily rehearsal planning", "children": [{"id": "49b1fcf5-c5c3-4514-abf4-c3ec99a3b22a", "type": "concept", "title": "Rehearsal goals"}, {"id": "60414ace-cc86-4386-a280-2cb93bdd1aac", "type": "concept", "title": "Time estimates"}, {"id": "aecd61e8-4f90-4ed5-8756-6edd0bf0f1b4", "type": "concept", "title": "Breaks and transitions"}], "description": "The point is to enter the room with priorities while remaining responsive to discoveries."}, {"id": "3ea81a9d-342e-4ea7-af17-5d6240ea1233", "type": "subtopic", "title": "Notes and documentation", "children": [{"id": "e2ab1c8e-87f7-4b67-8e59-a6a05fd233a2", "type": "concept", "title": "Rehearsal reports"}, {"id": "aceb827f-b490-4958-9e92-38afadd997dc", "type": "concept", "title": "Director notes"}, {"id": "56029396-0425-4db0-9dcf-bc9b70270d1e", "type": "concept", "title": "Revision tracking"}], "description": "Good documentation keeps the room aligned and preserves decisions."}, {"id": "ed93eff6-cad6-4e4a-84e1-86ce7737fd5e", "type": "subtopic", "title": "Room leadership", "children": [{"id": "1accea35-1e01-4cb0-80b8-a0771a9b62e5", "type": "concept", "title": "Check-ins"}, {"id": "ee27346b-95a5-4474-9ebf-3c3be687f86b", "type": "concept", "title": "Conflict management"}, {"id": "0adbf0bd-23f4-46ba-8995-a633bb3a6b27", "type": "concept", "title": "Inclusive room culture"}], "description": "Directors practice clarity, humility, pace, and care while holding artistic standards."}]}, {"id": "d5c9434c-3efc-4f68-bae8-8a82f6a0bd4d", "type": "topic", "title": "Pacing and Rhythm", "description": "Pacing is the audience's experience of time. Students learn how tempo, silence, interruption, transitions, and escalation shape meaning.", "children": [{"id": "0f4deda2-2ee8-4843-91cc-a119f1ae9bc0", "type": "subtopic", "title": "Tempo and beat changes", "children": [{"id": "0fe16b52-1461-4c20-8ff8-27625d5a6649", "type": "concept", "title": "Beat transitions"}, {"id": "6d99f42b-55cc-4bbd-86b7-d784cad7363d", "type": "concept", "title": "Acceleration and deceleration"}, {"id": "adbaedb1-286b-40f7-86cb-7e07f6952abb", "type": "concept", "title": "Energy mapping"}], "description": "Students identify shifts in energy and use them to prevent scenes from becoming flat."}, {"id": "bfd9f805-e609-426c-a7fa-c438788d73c0", "type": "subtopic", "title": "Silence and pause", "children": [{"id": "82a40549-f0b9-4574-bc4e-8b49baf83aec", "type": "concept", "title": "Active silence"}, {"id": "4f460758-b8b8-401b-a091-59b8ad243c07", "type": "concept", "title": "Comic timing"}, {"id": "4ee4eaec-f514-4c31-b145-2e99b4b980be", "type": "concept", "title": "Tension and release"}], "description": "The goal is to understand silence as action, pressure, thought, and relationship."}, {"id": "41229528-c6ca-4437-9369-25418cf1aee8", "type": "subtopic", "title": "Transitions", "children": [{"id": "33de9dd5-d97d-4bf4-8991-e640c235838b", "type": "concept", "title": "Blackouts and crossfades"}, {"id": "e108404d-dcae-45d7-85c9-ad64cc33ad56", "type": "concept", "title": "Music and sound bridges"}, {"id": "a0da1e14-3bcc-4c71-9bb1-0c4cb2b9ec8d", "type": "concept", "title": "Crew and actor choreography"}], "description": "Scene changes are part of the story and can carry mood, information, and momentum."}, {"id": "66ae6d4e-79d1-44a9-9503-f762aa18e04e", "type": "subtopic", "title": "Run-through analysis", "children": [{"id": "b94197e6-1899-4528-bb8a-cec031683079", "type": "concept", "title": "Where attention drops"}, {"id": "817e239f-404a-4591-a63a-a0586b7b51b0", "type": "concept", "title": "Rhythmic variety"}, {"id": "a992556a-2228-41c3-bc32-347add966054", "type": "concept", "title": "Notes after runs"}], "description": "Students learn to diagnose pacing problems from the audience's perspective."}]}, {"id": "32c51026-0df8-4e40-8882-0ae49cf7aded", "type": "topic", "title": "Collaboration with Designers", "description": "Directors lead through collaboration, not solitary control. Students learn how to invite design thinking early and keep artistic departments aligned.", "children": [{"id": "9ecd04c8-0db4-4627-b82b-a3c0313d3e34", "type": "subtopic", "title": "Design conversations", "children": [{"id": "a6e37598-979e-4c4d-82af-61eba4ca3d39", "type": "concept", "ti