insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('e647bf55-5ebf-45b9-971b-9300a49f9aff', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'The Director''s Vision', 'This section frames directing as interpretive leadership. Students learn to articulate a clear reason for a production and translate that reason into choices the whole team can use.', 0),
  ('42da9df3-f387-425d-b998-816143f6f5f7', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'e647bf55-5ebf-45b9-971b-9300a49f9aff', 'subtopic'::public.curated_course_node_type, 'Point of view and purpose', 'The goal is to move beyond liking a play toward making an argument for why it belongs on stage now.', 0),
  ('a72592be-90f6-4356-ad5d-c2a7137667d4', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '42da9df3-f387-425d-b998-816143f6f5f7', 'concept'::public.curated_course_node_type, 'Why this play now', null, 0),
  ('3435fa92-bcff-4135-8442-48a3103983f8', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '42da9df3-f387-425d-b998-816143f6f5f7', 'concept'::public.curated_course_node_type, 'Audience and community', null, 1),
  ('0cc575fd-301d-4b62-8b5b-06d5377d9b36', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '42da9df3-f387-425d-b998-816143f6f5f7', 'concept'::public.curated_course_node_type, 'Personal response versus production purpose', null, 2),
  ('80325a89-5a61-4012-9c76-0d2810dc284b', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'e647bf55-5ebf-45b9-971b-9300a49f9aff', 'subtopic'::public.curated_course_node_type, 'Theatrical world and rules', 'Students define the world the production asks the audience to enter, including its style, behavior, time, and sensory logic.', 1),
  ('24661fd0-333f-4282-b89d-1d3fdb433ead', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '80325a89-5a61-4012-9c76-0d2810dc284b', 'concept'::public.curated_course_node_type, 'Realism and theatricality', null, 0),
  ('3982e096-eed1-4ca4-9a95-e6ad290c75f9', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '80325a89-5a61-4012-9c76-0d2810dc284b', 'concept'::public.curated_course_node_type, 'Rules of space and time', null, 1),
  ('2851ac7b-8fc4-497b-8e30-2983955974a7', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '80325a89-5a61-4012-9c76-0d2810dc284b', 'concept'::public.curated_course_node_type, 'Tone and genre expectations', null, 2),
  ('0a637b1b-9018-4bcf-b4d4-569a1abcedd7', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'e647bf55-5ebf-45b9-971b-9300a49f9aff', 'subtopic'::public.curated_course_node_type, 'Director''s statement', 'A short statement helps collaborators understand the production''s north star without closing down discovery.', 2),
  ('52e24eeb-b985-495f-a9ec-6a34df77e5da', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '0a637b1b-9018-4bcf-b4d4-569a1abcedd7', 'concept'::public.curated_course_node_type, 'One-sentence premise', null, 0),
  ('58af7386-0ffa-4f77-a979-3b9f69d596a1', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '0a637b1b-9018-4bcf-b4d4-569a1abcedd7', 'concept'::public.curated_course_node_type, 'Core image or question', null, 1),
  ('0f202d19-5657-477b-84c3-34067fa13a45', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '0a637b1b-9018-4bcf-b4d4-569a1abcedd7', 'concept'::public.curated_course_node_type, 'Language for actors and designers', null, 2),
  ('12c51570-0a3f-4888-b612-09000abdfb96', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'e647bf55-5ebf-45b9-971b-9300a49f9aff', 'subtopic'::public.curated_course_node_type, 'Ethical and cultural stakes', 'Vision includes responsibility for the social meanings the production creates.', 3),
  ('d0452894-ceac-48ab-80fb-7ad33c91cd48', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '12c51570-0a3f-4888-b612-09000abdfb96', 'concept'::public.curated_course_node_type, 'Representation and harm', null, 0),
  ('26dca003-89b2-4377-a803-0c4275ab7962', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '12c51570-0a3f-4888-b612-09000abdfb96', 'concept'::public.curated_course_node_type, 'Community context', null, 1),
  ('52a7e911-9b2d-4fab-8107-a09bf0c82773', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '12c51570-0a3f-4888-b612-09000abdfb96', 'concept'::public.curated_course_node_type, 'Consultation and accountability', null, 2),
  ('8c25921f-ddbe-4b0f-b450-416008904ac0', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'Script Analysis for Directors', 'Directors analyze scripts to discover action, event, relationship, structure, and playable choices. The point is to prepare for rehearsal, not only to write about literature.', 1),
  ('10dca246-024d-408e-b2a2-ebd0c52eeef3', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '8c25921f-ddbe-4b0f-b450-416008904ac0', 'subtopic'::public.curated_course_node_type, 'Dramatic action and events', 'Students learn to find what changes in a scene and why that change matters.', 0),
  ('6645b502-0807-4aa3-b93d-fb0b62b55442', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '10dca246-024d-408e-b2a2-ebd0c52eeef3', 'concept'::public.curated_course_node_type, 'Event mapping', null, 0),
  ('573b45e3-58a7-4133-9cd7-d61e5594ed60', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '10dca246-024d-408e-b2a2-ebd0c52eeef3', 'concept'::public.curated_course_node_type, 'Triggers and consequences', null, 1),
  ('fc8fbc3b-f1b3-46a9-8613-8837928a050f', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '10dca246-024d-408e-b2a2-ebd0c52eeef3', 'concept'::public.curated_course_node_type, 'Scene objectives', null, 2),
  ('9306717d-d19a-42d3-9589-4254af500d23', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '8c25921f-ddbe-4b0f-b450-416008904ac0', 'subtopic'::public.curated_course_node_type, 'Character objectives and obstacles', 'Directors need actor-friendly language for desire, resistance, tactics, and stakes.', 1),
  ('858626f6-5898-4668-b515-68d750f76448', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '9306717d-d19a-42d3-9589-4254af500d23', 'concept'::public.curated_course_node_type, 'Want and need', null, 0),
  ('397ce9ce-6302-4ad8-9f25-6372c4958455', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '9306717d-d19a-42d3-9589-4254af500d23', 'concept'::public.curated_course_node_type, 'Obstacles', null, 1),
  ('976d163f-9649-4f0b-a7bf-fc7bceaf9a31', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '9306717d-d19a-42d3-9589-4254af500d23', 'concept'::public.curated_course_node_type, 'Tactics and adjustments', null, 2),
  ('d2e84c7a-02cf-4464-b418-fed858716f12', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '8c25921f-ddbe-4b0f-b450-416008904ac0', 'subtopic'::public.curated_course_node_type, 'Structure, rhythm, and arc', 'Students learn how scenes build pressure and how a full play organizes audience attention.', 2),
  ('ec3d65ca-b671-40f4-88b7-fb21c047ffd4', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'd2e84c7a-02cf-4464-b418-fed858716f12', 'concept'::public.curated_course_node_type, 'Beats and units', null, 0),
  ('867b43fc-26cf-4d77-acd3-482480c9d171', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'd2e84c7a-02cf-4464-b418-fed858716f12', 'concept'::public.curated_course_node_type, 'Rising and falling action', null, 1),
  ('5ee8ab44-9d7f-4f28-98b5-3591a525eef7', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'd2e84c7a-02cf-4464-b418-fed858716f12', 'concept'::public.curated_course_node_type, 'Reversals and discoveries', null, 2),
  ('eb0ccc52-3262-4bef-8c21-b6d0712f990d', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '8c25921f-ddbe-4b0f-b450-416008904ac0', 'subtopic'::public.curated_course_node_type, 'Production demands', 'Analysis also identifies staging, design, casting, intimacy, violence, dialect, and access needs.', 3),
  ('80d17ccb-f6d4-4c2c-bf39-674b548481d0', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'eb0ccc52-3262-4bef-8c21-b6d0712f990d', 'concept'::public.curated_course_node_type, 'Designable moments', null, 0),
  ('05041c4f-3397-44c4-82ee-53c5032aaac5', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'eb0ccc52-3262-4bef-8c21-b6d0712f990d', 'concept'::public.curated_course_node_type, 'Special skills and safety', null, 1),
  ('9bfccee2-b8ef-4461-b3fe-f31d6eebb989', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'eb0ccc52-3262-4bef-8c21-b6d0712f990d', 'concept'::public.curated_course_node_type, 'Research questions', null, 2),
  ('7c135adf-f18e-4ea0-9cf9-7574646b3e07', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'Concept Development', 'Concept development turns analysis into a practical artistic frame. Students learn to make choices that are specific enough to guide rehearsal and flexible enough to evolve.', 2),
  ('70a941aa-5a60-4483-ab4f-58a520e0b1e4', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '7c135adf-f18e-4ea0-9cf9-7574646b3e07', 'subtopic'::public.curated_course_node_type, 'Research into concept', 'Students practice converting historical, social, visual, and dramaturgical research into a coherent production idea.', 0),
  ('401206fb-e5cb-4e7c-8fe7-189dc4fa3c0f', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '70a941aa-5a60-4483-ab4f-58a520e0b1e4', 'concept'::public.curated_course_node_type, 'Research packets', null, 0),
  ('aafd1f95-54f4-4207-9e0e-1221b3287da3', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '70a941aa-5a60-4483-ab4f-58a520e0b1e4', 'concept'::public.curated_course_node_type, 'Visual references', null, 1),
  ('925911c7-6e02-4f42-9b92-91e1aab81271', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '70a941aa-5a60-4483-ab4f-58a520e0b1e4', 'concept'::public.curated_course_node_type, 'Historical pressure points', null, 2),
  ('40f26dac-3efa-4723-8c56-43586e30e642', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '7c135adf-f18e-4ea0-9cf9-7574646b3e07', 'subtopic'::public.curated_course_node_type, 'Style and genre', 'The director decides how the production behaves theatrically, from realism to heightened form.', 1);
