  ('74339adb-984f-4288-8e55-e35711fa9ab5', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'b8de18e4-da04-4865-ad14-b93d962a944e', 'concept'::public.curated_course_node_type, 'Mood boards', null, 1),
  ('35a989f1-d769-4914-befd-69e78559ab53', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'b8de18e4-da04-4865-ad14-b93d962a944e', 'concept'::public.curated_course_node_type, 'Questions for collaborators', null, 2),
  ('3c260cb6-6622-4728-bcba-d6f5dfc31f9b', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'Casting', 'Casting is both artistic composition and ethical responsibility. Students learn how casting choices shape meaning, rehearsal room trust, and audience interpretation.', 3),
