  ('043ff5d2-cea1-4d70-b8e3-597486e3c32d', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '7ec9044d-2fc0-4862-8f84-54663a415bf8', 'concept'::public.curated_course_node_type, 'Sides and monologues', null, 0),
