  ('ad197dbe-10a7-4ee3-a494-21cdcdfb2262', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ffbc3ff2-d591-43b4-b6ba-5bd522ef3325', 'subtopic'::public.curated_course_node_type, 'Focus and composition', 'Students learn how grouping, levels, distance, and orientation guide the audience''s eye.', 0),
  ('c25e7f24-79ba-44d2-ab2c-e95a10a90756', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ad197dbe-10a7-4ee3-a494-21cdcdfb2262', 'concept'::public.curated_course_node_type, 'Stage pictures', null, 0),
  ('c57014c9-8135-40c5-aece-a6ec72a91c8c', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ad197dbe-10a7-4ee3-a494-21cdcdfb2262', 'concept'::public.curated_course_node_type, 'Levels and planes', null, 1),
  ('e8b3a1a4-edc5-410c-81e0-5ab1e5d75d15', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ad197dbe-10a7-4ee3-a494-21cdcdfb2262', 'concept'::public.curated_course_node_type, 'Sightlines and focus', null, 2),
  ('bc1b99df-22e3-47aa-a310-07138ff9a9f9', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ffbc3ff2-d591-43b4-b6ba-5bd522ef3325', 'subtopic'::public.curated_course_node_type, 'Movement motivated by action', 'Blocking should come from character need and dramatic event, not decorative traffic.', 1),
  ('f80736d9-c109-4801-bd81-b073fa585504', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'bc1b99df-22e3-47aa-a310-07138ff9a9f9', 'concept'::public.curated_course_node_type, 'Entrances and exits', null, 0),
