  ('e5b85b14-74fb-464b-ad20-884e0b0bed54', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '9806a05d-2e7a-46f2-a2e7-c96074c0d606', 'concept'::public.curated_course_node_type, 'Proxemics', null, 0),
