  ('ece24c4c-1c08-4d99-83ae-faf47ecdf599', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'Working with Actors', 'Directing actors requires precise language, trust, listening, and respect for process. Students learn how to guide performance without controlling every impulse.', 5),
  ('4c246b00-514f-47d7-ba64-55c23edbfa08', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ece24c4c-1c08-4d99-83ae-faf47ecdf599', 'subtopic'::public.curated_course_node_type, 'Playable notes', 'Students learn to give notes actors can act, rather than abstract judgments or results-only instructions.', 0),
  ('bf5914e0-bc46-405c-bfe6-8d2f3e496583', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '4c246b00-514f-47d7-ba64-55c23edbfa08', 'concept'::public.curated_course_node_type, 'Action verbs', null, 0),
  ('db103ed6-16bb-4a82-89e6-028cd12f10c0', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '4c246b00-514f-47d7-ba64-55c23edbfa08', 'concept'::public.curated_course_node_type, 'Objectives and tactics', null, 1),
  ('93149fd6-715e-4b29-b7db-85daad574b3a', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '4c246b00-514f-47d7-ba64-55c23edbfa08', 'concept'::public.curated_course_node_type, 'Avoiding line readings', null, 2),
  ('72ed0659-3050-4bb9-8a53-cc07e2eecfd8', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ece24c4c-1c08-4d99-83ae-faf47ecdf599', 'subtopic'::public.curated_course_node_type, 'Rehearsal room trust', 'The director sets the conditions for risk, rigor, consent, and creative honesty.', 1),
  ('43c959d9-6d54-4ccf-8b80-3ae7a59e722b', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '72ed0659-3050-4bb9-8a53-cc07e2eecfd8', 'concept'::public.curated_course_node_type, 'Room agreements', null, 0),
  ('7661580e-1620-45c0-9455-15d56e01118b', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '72ed0659-3050-4bb9-8a53-cc07e2eecfd8', 'concept'::public.curated_course_node_type, 'Consent and intimacy boundaries', null, 1),
  ('49e08bb1-11e0-4d1f-8a47-0d80a60563e2', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '72ed0659-3050-4bb9-8a53-cc07e2eecfd8', 'concept'::public.curated_course_node_type, 'Psychological safety', null, 2),
  ('53b66d63-6141-4b2a-bc71-50657ffb10fa', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ece24c4c-1c08-4d99-83ae-faf47ecdf599', 'subtopic'::public.curated_course_node_type, 'Improvisation and exploration', 'Exercises can unlock relationship, given circumstances, rhythm, and physical choices.', 2),
  ('02a165ea-5997-4c0a-bda7-e94983c3e823', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '53b66d63-6141-4b2a-bc71-50657ffb10fa', 'concept'::public.curated_course_node_type, 'Status exercises', null, 0),
  ('3ed401b8-6144-40ed-8c72-bdf8b1e5f1fb', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '53b66d63-6141-4b2a-bc71-50657ffb10fa', 'concept'::public.curated_course_node_type, 'Backstory improvisation', null, 1),
  ('027cf1c5-5afe-408c-8986-260762f1a68a', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '53b66d63-6141-4b2a-bc71-50657ffb10fa', 'concept'::public.curated_course_node_type, 'Physical score experiments', null, 2),
