  ('74cdf90d-7b3d-4e70-86f4-e1f4da762d12', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'dee122ed-d05f-477a-896a-1c908c7c109a', 'concept'::public.curated_course_node_type, 'Notes after runs', null, 0),
