  ('3bd88ea4-d7c1-4a2a-a48b-0efde90e1e25', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', null, 'topic'::public.curated_course_node_type, 'Rehearsal Planning and Structure', 'A director''s plan turns limited time into focused discovery. Students learn to organize rehearsals that balance table work, experimentation, staging, repetition, and notes.', 6),
