  ('81efe1c7-5a80-42ec-aeba-89bf54f10d06', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', 'ff0ea278-7bb7-4676-9578-4d691ca1f219', 'concept'::public.curated_course_node_type, 'Table work', null, 0),
