  ('49b1fcf5-c5c3-4514-abf4-c3ec99a3b22a', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '603a1da1-4001-4085-b3c2-3477df76c62f', 'concept'::public.curated_course_node_type, 'Rehearsal goals', null, 0),
  ('60414ace-cc86-4386-a280-2cb93bdd1aac', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '603a1da1-4001-4085-b3c2-3477df76c62f', 'concept'::public.curated_course_node_type, 'Time estimates', null, 1),
