  ('e2ab1c8e-87f7-4b67-8e59-a6a05fd233a2', 'd6e7f8a9-0b1c-4d26-9f56-6a7b8c9d0e26', '3ea81a9d-342e-4ea7-af17-5d6240ea1233', 'concept'::public.curated_course_node_type, 'Rehearsal reports', null, 0),
